document.addEventListener("DOMContentLoaded",function(){let e=document.querySelectorAll("[data-ajax-href]");e&&e.forEach(e=>{e.addEventListener("click",t=>{t.preventDefault();var n=new FormData;n.append("authToken",ContaoTranslator.authToken),fetch(e.dataset.ajaxHref,{method:"POST",headers:{"x-requested-with":"XMLHttpRequest"},body:n}).then(function(e){return e.json()}).then(function(e){"success"===e.status&&window.location.reload()})})})});